#!/usr/bin/env node
// Builds cyberpunk-ui.css by concatenating the eight stylesheets.
//
//   node scripts/build-bundle.js           write the bundle
//   node scripts/build-bundle.js --check   fail if the bundle is stale
//
// Why this exists. The barrel used to be eight `@import` lines, which is the
// right shape for a bundler and the wrong one for a browser: a `<link>` to it
// costs 276 bytes, and the imports inside cannot be discovered until that
// response lands and parses. One stylesheet became nine serialised,
// render-blocking round trips for anyone loading the kit from a CDN — the path
// the README recommends to people with no build step, which is exactly the
// audience least able to work around it.
//
// Concatenation is the whole build. No minifier, no dependency, no config: the
// package still has zero of all three, and jsDelivr already serves a minified
// copy of whatever it is given (clean-css, at `/cyberpunk-ui.min.css`).
//
// The generated file is committed, because the package ships `*.css` straight
// from the repo with no publish step to generate it. That makes staleness the
// real risk, which is what --check exists for: it runs in CI and in
// `npm run check`, and fails when a part has been edited without a rebuild.

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const BUNDLE = 'cyberpunk-ui.css';

// Order matters and is not alphabetical: tokens first, because every other
// file reads the custom properties it declares.
const PARTS = [
  'tokens.css',
  'effects.css',
  'components.css',
  'containers.css',
  'navigation.css',
  'table.css',
  'forms.css',
  'feedback.css',
];

const BANNER = '/*! @laddtnov/cyberpunk-ui | MIT | github.com/laddtnov/cyberpunk-ui */';

// Each part carries its own `/*! ... */` banner. One in the bundle is a
// licence notice; eight is noise, so the per-file ones are dropped and the
// filename is kept as an ordinary comment to keep the bundle navigable.
function build() {
  const sections = PARTS.map((file) => {
    const css = fs.readFileSync(path.join(ROOT, file), 'utf8').replace(/^\/\*![^]*?\*\/\s*/, '');
    return `/* ── ${file} ${'─'.repeat(Math.max(0, 56 - file.length))} */\n${css.trim()}\n`;
  });

  return `${BANNER}\n/* Generated by scripts/build-bundle.js — edit the parts, not this file. */\n\n${sections.join('\n')}`;
}

// check-conventions.js reads PARTS from here so the list of stylesheets has
// one home. A new file added to the repo but missing from PARTS would build a
// bundle that is internally consistent and quietly incomplete; that check is
// what catches it.
module.exports = { PARTS, BUNDLE };

if (require.main !== module) return;

const expected = build();
const bundlePath = path.join(ROOT, BUNDLE);
const actual = fs.existsSync(bundlePath) ? fs.readFileSync(bundlePath, 'utf8') : '';

if (process.argv.includes('--check')) {
  if (actual !== expected) {
    console.error(`${BUNDLE} is stale — a stylesheet changed without a rebuild.`);
    console.error('Run: npm run build:css');
    process.exit(1);
  }
  console.log(`${BUNDLE} is up to date — ${PARTS.length} stylesheets, ${(Buffer.byteLength(expected) / 1024).toFixed(1)} kB.`);
  process.exit(0);
}

fs.writeFileSync(bundlePath, expected);
console.log(`${BUNDLE} written — ${PARTS.length} stylesheets, ${(Buffer.byteLength(expected) / 1024).toFixed(1)} kB, 1 request.`);
